#include <opencv2/opencv.hpp>
#include <iostream>
#include <filesystem>
int main(){ cv::Size pattern(9,6); float square=0.024f; std::vector<cv::Point3f> obj; for(int y=0;y<pattern.height;y++) for(int x=0;x<pattern.width;x++) obj.emplace_back(x*square,y*square,0); std::vector<std::vector<cv::Point3f>> objs; std::vector<std::vector<cv::Point2f>> imgs; cv::Size sz; for(auto& e:std::filesystem::directory_iterator("data/calibration")){ auto im=cv::imread(e.path().string()); if(im.empty()) continue; cv::Mat g; cv::cvtColor(im,g,cv::COLOR_BGR2GRAY); sz=g.size(); std::vector<cv::Point2f> c; if(cv::findChessboardCorners(g,pattern,c)){ cv::cornerSubPix(g,c,{11,11},{-1,-1},{cv::TermCriteria::EPS+cv::TermCriteria::COUNT,30,1e-3}); objs.push_back(obj); imgs.push_back(c);} } if(objs.empty()){ std::cerr<<"Añade imágenes en data/calibration\n"; return 1;} cv::Mat K,dist; std::vector<cv::Mat> r,t; double rms=cv::calibrateCamera(objs,imgs,sz,K,dist,r,t); std::cout<<"RMS "<<rms<<"\nK=\n"<<K<<"\ndist="<<dist<<"\n"; }
